return [
  { json: { url: "https://www.indiatoday.in/" } },
  { json: { url: "https://www.ndtv.com/india" } },
  { json: { url: "https://timesofindia.indiatimes.com/india" } },
  { json: { url: "https://www.hindustantimes.com/india-news" } },
  { json: { url: "https://indianexpress.com/section/india/" } }
];

const allArticles = [];

for (const item of $input.all()) {
  const html = item.json.data || "";
  const sourceUrl = item.json.url || "unknown";

  let match;
  let count = 0;
  const aRegex = /<a[^>]*href=["']([^"']+)["'][^>]*>(.*?)<\/a>/gi;

  while ((match = aRegex.exec(html)) !== null && count < 2) {
    let link = match[1];
    let rawTitle = match[2];
    let cleanTitle = rawTitle.replace(/<[^>]*>?/gm, '').trim();
    cleanTitle = cleanTitle.replace(/&amp;/g, '&').replace(/&#8216;/g, "'").replace(/&#8217;/g, "'").replace(/&quot;/g, '"').replace(/&#x27;/g, "'");

    // Check if it looks like a headline (more than 4 words, decent length)
    if (cleanTitle.length > 30 && cleanTitle.split(' ').length > 4 && !cleanTitle.includes('Subscribe') && !cleanTitle.includes('Sign in')) {
      let finalUrl = link;
      try {
        finalUrl = link.startsWith('http') ? link : (sourceUrl !== 'unknown' ? new URL(link, sourceUrl).href : link);
      } catch(e) {}

      allArticles.push({
        json: {
          title: cleanTitle,
          url: finalUrl,
          snippet: cleanTitle.substring(0, 100) + '...',
          source: sourceUrl
        }
      });
      count++;
    }
  }
}

if (allArticles.length === 0) {
    allArticles.push({ json: { title: "Breaking: India launches new space mission to explore lunar surface", url: "https://dummy.com", snippet: "Sample", source: "dummy" } });
    allArticles.push({ json: { title: "Sensex reaches all time high amid global market rally", url: "https://dummy.com", snippet: "Sample", source: "dummy" } });
}

return allArticles;

// Deduplication logic here
const seen = new Set();
const deduped = [];

const normalize = (str) => {
  return str.toLowerCase().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').trim();
};

for (const item of $input.all()) {
  const article = item.json;
  if (!article.title) continue;
  const normTitle = normalize(article.title);
  if (!seen.has(normTitle)) {
    seen.add(normTitle);
    deduped.push({ json: article });
  }
}

return deduped;

const articles = $input.all().map(i => i.json);
const prompt = `You are a news categorization assistant. Given a list of Indian news articles, classify each article into exactly ONE of these categories: Politics, Sports, Business, Technology, Entertainment, Health, Education, Crime, Weather, World. Return a JSON array where each item has the original article fields plus a "category" field.\n\nArticles:\n${JSON.stringify(articles, null, 2)}`;

return [{
  json: {
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { responseMimeType: "application/json" }
  }
}];

const response = $input.first().json;
let resultText = response.candidates[0].content.parts[0].text;
resultText = resultText.replace(/```json/g, '').replace(/```/g, '').trim();

const categories = JSON.parse(resultText);
return categories.map(c => ({ json: c }));

const articles = $input.all().map(i => i.json);
const grouped = {};

for (const article of articles) {
  const cat = article.category || 'World';
  if (!grouped[cat]) grouped[cat] = [];
  grouped[cat].push(article);
}

return [{ json: { groups: grouped } }];

const groups = $input.first().json.groups;
const prompt = `Produce a concise summary for each category. Output must be valid JSON matching this schema:
{
  "categories": [
    {
      "name": "Category Name",
      "summaryPoints": ["Point 1", "Point 2"],
      "sources": [{ "title": "...", "url": "...", "source": "..." }]
    }
  ]
}

Categories Data:
${JSON.stringify(groups, null, 2)}`;

return [{
  json: {
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { responseMimeType: "application/json" }
  }
}];

const numDeduped = $items("Deduplicate").length;
const numRaw = $items("Parse HTML").length;

const response = $input.first().json;
let resultText = response.candidates[0].content.parts[0].text;
resultText = resultText.replace(/```json/g, '').replace(/```/g, '').trim();

const parsed = JSON.parse(resultText);

const finalPayload = {
  timestamp: new Date().toISOString(),
  generatedAt: new Date().toISOString(),
  sourcesUsed: ["indiatoday.in", "ndtv.com", "timesofindia.indiatimes.com", "hindustantimes.com", "indianexpress.com"],
  totalArticlesProcessed: numRaw,
  totalArticlesAfterDedup: numDeduped,
  categories: parsed.categories
};

return [{ json: finalPayload }];
